 const payments=p.data.payments.filter(x=>inRange(x.created_at));const total=payments.reduce((sum,x)=>sum+x.amount_cents,0);
 const completed=p.data.appointments.filter(a=>a.status==='completed'&&inRange(a.starts_at));
